import React, { useEffect, useState } from 'react';
import api from '../api/axios';
import MovieCard from '../components/MovieCard';
import styles from './Home.module.css';

export default function Home() {
  const [movies, setMovies] = useState([]);
  const [search, setSearch] = useState('');
  const [genre, setGenre] = useState('');
  const [loading, setLoading] = useState(true);

  const genres = ['Action', 'Comedy', 'Drama', 'Horror', 'Romance', 'Thriller', 'Sci-Fi'];

  useEffect(() => {
    fetchMovies();
  }, [search, genre]);

  const fetchMovies = async () => {
    setLoading(true);
    try {
      const params = {};
      if (search) params.search = search;
      if (genre) params.genre = genre;
      const { data } = await api.get('/movies', { params });
      setMovies(data);
    } catch (err) {
      console.error(err);
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className={styles.container}>
      <div className={styles.hero}>
        <h1>Book Your Movie Experience</h1>
        <p>Browse the latest movies and grab your seats</p>
        <input
          className={styles.search}
          placeholder="Search movies..."
          value={search}
          onChange={(e) => setSearch(e.target.value)}
        />
      </div>

      <div className={styles.filters}>
        <button className={!genre ? styles.active : ''} onClick={() => setGenre('')}>All</button>
        {genres.map((g) => (
          <button key={g} className={genre === g ? styles.active : ''} onClick={() => setGenre(g)}>{g}</button>
        ))}
      </div>

      {loading ? (
        <p className={styles.loading}>Loading movies...</p>
      ) : movies.length === 0 ? (
        <p className={styles.loading}>No movies found.</p>
      ) : (
        <div className={styles.grid}>
          {movies.map((movie) => <MovieCard key={movie._id} movie={movie} />)}
        </div>
      )}
    </div>
  );
}
